export const FRAMES=Object.freeze(['narrow','balanced']),ARMS=Object.freeze(['short','average','long']),POSES=Object.freeze(['neutral','guard','punch']),CLOTHING=Object.freeze(['sleeveless','fitted_sleeve','outer']),VIEWS=Object.freeze(['front','right']);
const ARM_REACH=Object.freeze({short:12,average:15,long:18}),POSE=Object.freeze({neutral:{handY:43,extra:0},guard:{handY:24,extra:1},punch:{handY:28,extra:10}}),FRAME=Object.freeze({narrow:22,balanced:19});
export const ACCOUNTING=Object.freeze({logicalPresentations:108,naiveFullBodies:108,authoredPngs:23,avoidedFullBodies:85,ratio:'5:1',classifications:Object.freeze({SHARED:1,METADATA_ONLY:3,STRUCTURE_SPECIFIC:2,POSE_SPECIFIC:0,VIEW_SPECIFIC:0,CLOTHING_SPECIFIC:2,CLOTHING_X_POSE:0,VIEW_X_POSE:12,STRUCTURE_X_CLOTHING:2,VIEW_X_CLOTHING_X_POSE:6,STRUCTURE_X_CLOTHING_X_POSE:0,COMPOSITE_EXCEPTION:0}),worstBoundary:'View × fitted sleeve × pose (contained as shared frame-compatible sleeve pose assets)'});
function known(v,set,name){if(!set.includes(v))throw new Error(`unknown ${name}: ${v}`)}function p(x,y){return Object.freeze({x,y})}
const LAYERS=Object.freeze({neutral:Object.freeze(['rearArm','torso','torsoGarment','frontArm','frontSleeve','equipment']),guard:Object.freeze(['rearArm','rearSleeve','torso','torsoGarment','frontArm','frontSleeve','equipment']),punch:Object.freeze(['rearArm','rearSleeve','torso','torsoGarment','frontArm','frontSleeve','equipment'])});
export function resolveSleeveOcclusion(options={}){const s={frame:'balanced',armLength:'average',pose:'neutral',clothing:'fitted_sleeve',view:'front',...options};known(s.frame,FRAMES,'frame');known(s.armLength,ARMS,'armLength');known(s.pose,POSES,'pose');known(s.clothing,CLOTHING,'clothing');known(s.view,VIEWS,'view');const shoulder=p(FRAME[s.frame],28),hand=p(64-FRAME[s.frame]+ARM_REACH[s.armLength]+POSE[s.pose].extra,POSE[s.pose].handY),elbow=p(Math.round((shoulder.x+hand.x)/2),Math.round((shoulder.y+hand.y)/2)),anchors=Object.freeze({head:p(32,14),eye_left:p(29,13),eye_right:p(35,13),nose:p(32,16),shoulder_right:shoulder,elbow_right:elbow,hand_right:hand});const sleeve=s.clothing==='fitted_sleeve'?`sleeve.fitted.${s.view}.${s.pose}`:null,torso=s.clothing==='outer'?`outer.${s.view}`:s.clothing==='fitted_sleeve'?`torsoGarment.fitted.${s.frame}`:`torso.${s.frame}`;return Object.freeze({...s,anchors,layerProfile:LAYERS[s.pose],components:Object.freeze([`arm.${s.view}.rear.${s.pose}`,torso,`arm.${s.view}.front.${s.pose}`,sleeve, 'weapon.shared.blade'].filter(Boolean)),attachment:Object.freeze({id:'blade',anchor:'hand_right',point:hand}),rendering:Object.freeze({integerPlacement:true,nearestNeighbor:true,fractionalScaling:false,smoothRotation:false,meshDeformation:false})})}
const F={torso:{narrow:'components/torso/narrow.png',balanced:'components/torso/balanced.png'},arm:(v,side,p)=>`components/shared/arm-${v}-${side}-${p}.png`,sleeve:(v,p)=>`components/sleeve/fitted-${v}-${p}.png`,outer:v=>`components/outer/outer-${v}.png`,blade:'components/shared/blade.png'},C=new Map();function load(x){if(!C.has(x)){const i=new Image();i.src=x;C.set(x,i)}return C.get(x)}function draw(ctx,x,a,b){const i=load(x);if(i.complete)ctx.drawImage(i,Math.round(a),Math.round(b))}
export function drawSleeveOcclusion(ctx,m,debug=false){ctx.imageSmoothingEnabled=false;ctx.fillStyle='#17202a';ctx.fillRect(0,0,64,64);const a=m.anchors;draw(ctx,F.arm(m.view,'rear',m.pose),a.shoulder_right.x-5,27);draw(ctx,m.clothing==='outer'?F.outer(m.view):F.torso[m.frame],20,27);if(m.clothing==='fitted_sleeve')draw(ctx,F.sleeve(m.view,m.pose),a.shoulder_right.x-4,27);draw(ctx,F.arm(m.view,'front',m.pose),a.shoulder_right.x-2,27);draw(ctx,F.blade,a.hand_right.x+1,a.hand_right.y-14);if(debug){ctx.fillStyle='#ffdf69';Object.entries(a).forEach(([n,q])=>ctx.fillRect(q.x-1,q.y-1,3,3))}}
function init(){const c=document.querySelector('#preview');if(!c)return;const f=document.querySelector('#controls'),d=document.querySelector('#details'),g=document.querySelector('#debug'),r=()=>{const m=resolveSleeveOcclusion(Object.fromEntries(new FormData(f)));drawSleeveOcclusion(c.getContext('2d'),m,g.checked);d.textContent=JSON.stringify(m,null,2)};f.addEventListener('change',r);g.addEventListener('change',r);r()}if(typeof document!=='undefined')document.addEventListener('DOMContentLoaded',init);
